<?php require 'includes/db.php';require 'includes/functions.php';login_required();$cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart/');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$a=trim($_POST['address']??'');$c=trim($_POST['city']??'');$p=trim($_POST['postal']??'');if(!$n||!$a||!$c||!preg_match('/^[A-Za-z0-9 -]{4,10}$/',$p))$err='Enter valid shipping information.';else{$conn->begin_transaction();try{$total=0;$list=[];foreach($cart as $id=>$qty){$id=(int)$id;$qty=(int)$qty;$s=$conn->prepare('SELECT id,title,price,stock FROM books WHERE id=? FOR UPDATE');$s->bind_param('i',$id);$s->execute();$bk=$s->get_result()->fetch_assoc();if(!$bk||$qty<1||$qty>$bk['stock'])throw new Exception('Stock changed. Please update your cart.');$total+=$bk['price']*$qty;$list[]=[$bk,$qty];}$uid=(int)$_SESSION['user_id'];$o=$conn->prepare('INSERT INTO orders(user_id,total,shipping_name,shipping_address,shipping_city,shipping_postal) VALUES(?,?,?,?,?,?)');$o->bind_param('idssss',$uid,$total,$n,$a,$c,$p);$o->execute();$oid=$conn->insert_id;foreach($list as [$bk,$qty]){$it=$conn->prepare('INSERT INTO order_items(order_id,book_id,title,price,quantity) VALUES(?,?,?,?,?)');$it->bind_param('iisdi',$oid,$bk['id'],$bk['title'],$bk['price'],$qty);$it->execute();$up=$conn->prepare('UPDATE books SET stock=stock-? WHERE id=?');$up->bind_param('ii',$qty,$bk['id']);$up->execute();}$conn->commit();unset($_SESSION['cart']);header('Location: orders/invoice.php?id='.$oid);exit;}catch(Throwable $e){$conn->rollback();$err=$e->getMessage();}}}$page_title='Checkout';include 'includes/header.php';?><div class="formbox"><h1>Shipping Details</h1><?php if($err):?><p class="notice error"><?=e($err)?></p><?php endif;?><form method="post" data-validate><label>Name</label><input name="name" required><label>Address</label><textarea name="address" required></textarea><label>City</label><input name="city" required><label>Postal Code</label><input name="postal" required><button class="btn">Place Order</button></form><p class="muted">Demo checkout does not collect payment details.</p></div><?php include 'includes/footer.php';?>
